def att_matrix(L):
    a = np.load(base+f'mlp_act_L{L}.npy').astype(np.float32)
    d = load(f'model.language_model.layers.{L}.mlp.down_proj.weight').float().numpy()
    return H[L+1] - H[L] - a @ d.T

print('L: Wait(loop) att | Think(stop) att | Wait(fin) att')
for L in range(24):
    att = att_matrix(L)
    def s(poss, r):
        vals = np.stack([att[t,p] for t,p in poss])
        nrm = np.array([rms[t,p] for t,p in poss])
        return float(((vals @ r) / nrm).mean())
    print('L%d attwait %.3f attthink %.3f wait_fin %.3f' % (L, s(pos_loop_wait, r_wait), s(pos_stop, r_think), s(pos_fin_all, r_wait)))

